#!/usr/bin/env bash
# Recreates the owner's ~/Documents/Pocket CEO/ for this eval case (generated by dev/make_evals.py).
set -e
python3 - <<'PY'
import base64, datetime, json, os, re
from pathlib import Path
S = json.loads(r"""{"anchor": "2026-11-19", "shift_dates": true, "files": {"decisions.md": "MjAyNi0xMC0wMiB8IGNhc2hmbG93IHwgQ2FzaCBjdXNoaW9uICQyLDAwMCB8IGZvbGxvdy11cDogbW9udGhseSBDU1YK", "profile.md": "", "money/rules.csv": "cGF0dGVybixjYXRlZ29yeSxidXNpbmVzc19wY3QsYWRkZWQsZXhhbXBsZQ0KQU1BWk9OLkNBLE9mZmljZSBleHBlbnNlcywxMDAsMjAyNi0xMS0xOSwNCg==", "money/invoices.csv": "", "money/transactions.csv": "", "memory/index.md": "IyBNZW1vcnkgaW5kZXgKClNlZSBwZW9wbGUubWQsIGN1c3RvbWVycy5tZCwgbW9uZXkubWQsIGdvYWxzLm1kLCBwcm9taXNlcy5tZCwgcHJlZmVyZW5jZXMubWQuCg==", "memory/preferences.md": "IyBQcmVmZXJlbmNlcwoKLSAyMDI2LTEwLTAyIChjaGF0KTogQ2FzaCBjdXNoaW9uOiBuZXZlciBsZXQgdGhlIGJ1c2luZXNzIGFjY291bnQgZ28gYmVsb3cgJDIsMDAwLgo=", "memory/customers.md": "", "receipts/2026/2026-09-03_staples_56.50.jpg": "/9j/IHBsYWNlaG9sZGVyIHJlY2VpcHQgaW1hZ2U=", "receipts/2026/2026-09-22_bestbuy_1695.00.jpg": "/9j/IHBsYWNlaG9sZGVyIHJlY2VpcHQgaW1hZ2U=", "receipts/2026/receipts-2026.csv": "", "receipts/2026/2026-07-03_staples_56.50.jpg": "/9j/IHBsYWNlaG9sZGVyIHJlY2VpcHQgaW1hZ2U=", "money/imports/2026-11-19_rbc-export.csv": ""}}""")
home = Path(os.path.expanduser("~/Documents/Pocket CEO"))
anchor = datetime.date.fromisoformat(S["anchor"])
shift = datetime.timedelta(weeks=round((datetime.date.today() - anchor).days / 7)) if S["shift_dates"] else datetime.timedelta(0)
mv = lambda m: (datetime.date.fromisoformat(m.group(0)) + shift).isoformat()
for rel, b64 in S["files"].items():
    data = base64.b64decode(b64)
    if shift and rel.endswith((".csv", ".md", ".json")):
        data = re.sub(r"\b20\d\d-\d\d-\d\d\b", mv, data.decode("utf-8")).encode("utf-8")
    rel = re.sub(r"20\d\d-\d\d-\d\d", mv, rel) if shift else rel
    p = home / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(data)
PY
